# Nebius blog post on MLPerf Inference v6.1, held against the v6.1 result file. python3 -I check_claims_nebius_v61.py
import json,hashlib,re
FILES=['raw/inf_6.1.json']; RAW={f:open(f,'rb').read() for f in FILES}
B=list(json.loads(RAW[FILES[0]]).values()); s=str; pc=lambda x,y:100*(x/y-1)
def mk(i,q,calc,st,got,out,note): return dict(id=i,quote=q,calc=calc,stated=st,delivered=got,outcome=out,note=note,label_mismatch=False)
def gi(a): return s(a)
NB=[x for x in B if x['Organization']=='Nebius']
def nb(sysn,m,sc):
    r=[x for x in NB if sysn in x['SystemName'] and x['Model']==m and x['Scenario']==sc]; assert len(r)==1,(sysn,m,sc,len(r)); return r[0]
def grp(x): return [y for y in B if y['Division']=='closed' and y['Availability']=='available' and y['Model']==x['Model'] and y['Scenario']==x['Scenario'] and gi(y['accelerator_model_name'])==gi(x['accelerator_model_name']) and y['total_accelerators']==x['total_accelerators']]
def rank(x): g=grp(x); return 1+sum(1 for y in g if y['Result']>x['Result']),len(g)
ORD={1:'1st',2:'2nd',3:'3rd'}; od=lambda r:ORD.get(r,f'{r}th')
cells=[('B200 n1','deepseek-r1','Server',55869,'2nd'),('B200 n1','deepseek-r1','Offline',56930,'2nd'),('B200 n1','gpt-oss-120b','Server',89856,'2nd'),('B200 n1','gpt-oss-120b','Offline',88491,'2nd'),
('B300 n1','deepseek-r1','Server',63909,'5th'),('B300 n1','deepseek-r1','Offline',69655,None),('B300 n1','qwen3-vl-235b-a22b','Server',112.29,'2nd'),('B300 n1','qwen3-vl-235b-a22b','Offline',131.48,'3rd'),('B300 n1','gpt-oss-120b','Server',108124,None),('B300 n1','gpt-oss-120b','Offline',108529,None),
('RTX PRO 6000','gpt-oss-120b','Server',14784,'2nd'),('RTX PRO 6000','gpt-oss-120b','Offline',15739,'1st'),('(4x GB300','qwen3-vl-235b-a22b','Server',64.62,'2nd'),('(4x GB300','qwen3-vl-235b-a22b','Offline',73.19,'1st'),
('(8x GB300','gpt-oss-120b','Server',127921,'2nd'),('(8x GB300','gpt-oss-120b','Offline',132236,'1st'),('(72x GB300','deepseek-r1','Server',603023,'1st'),('(72x GB300','deepseek-r1','Offline',689961,'1st'),('(72x GB300','gpt-oss-120b','Server',1122490,'2nd'),('(72x GB300','gpt-oss-120b','Offline',1186750,'2nd')]
vals_ok=True; rk_ok=True; rows=[]; firsts=0
for sysn,m,sc,v,r_st in cells:
    x=nb(sysn,m,sc); dec=2 if v<1000 and not float(v).is_integer() else 0
    okv=round(x['Result'],dec)==v if dec else int(x['Result']+0.5)==v
    r,N=rank(x); vals_ok&=okv
    if r_st is not None and od(r)!=r_st: rk_ok=False
    if r==1: firsts+=1
    rows.append((sysn,m[:6],sc[:3],x['Result'],f'{r}/{N}',okv))
NBL=[]
NBL.append(mk('NV1','Nebius achieved five first-place results across 20 available category entries','Nebius closed available v6.1 entries ranked among closed available entries with the same model, scenario, accelerator and accelerator count',"five first-place results, 20 category entries",f'{firsts} first places across {len([c for c in cells])} ranked-table entries','CONSISTENT' if firsts==5 and len(cells)==20 else 'BELOW','Our rank rule: entries with the same accelerator model and count. It reproduces every rank shown in the post table.'))
NBL.append(mk('NV2','Results table in the post, twenty values for six benchmark columns and six hardware configurations','Nebius entries in the v6.1 file, result field rounded to the digits printed','twenty table values',f'{sum(1 for r in rows if r[5])} of {len(rows)} values match the file to the digits printed','CONSISTENT' if vals_ok else 'BELOW',''))
NBL.append(mk('NV3','Rank labels printed beside the table values in the post','rank of each Nebius entry in its group of same model, scenario, accelerator and count',"seventeen printed ranks",'; '.join(f'{r[0].strip("()")} {r[1]} {r[2]} {r[4]}' for r in rows),'CONSISTENT' if rk_ok else 'BELOW','Three cells carry a dash instead of a rank (B300 DeepSeek R1 Offline, B300 gpt-oss 120B Server and Offline). The file ranks for those are 10 of 13, 6 of 13 and 8 of 13.'))
vr=[x for x in B if ('Rubin' in gi(x['accelerator_model_name']) or 'VR' in gi(x['accelerator_model_name'])) and x['Model']=='deepseek-r1']
orgs={x['Organization'] for x in B if any(k in gi(x['accelerator_model_name']) for k in('Rubin','VR2'))}
NBL.append(mk('NV4','Nebius was one of only two submitters in this round with results on Vera Rubin-based hardware.','v6.1 file entries whose accelerator name contains Rubin or VR200','one of two submitters',f'organizations: {sorted(orgs)}','CONSISTENT' if len(orgs)==2 and 'Nebius' in orgs else 'BELOW',''))
nsys=sorted({x['SystemName'] for x in NB}); mods=sorted({x['Model'] for x in NB}); both=all({x['Scenario'] for x in NB if x['Model']==m}>={'Server','Offline'} for m in mods)
NBL.append(mk('NV5','Seven system configurations span a wide range of inference hardware','distinct Nebius SystemName values in the v6.1 file','seven system configurations',f'{len(nsys)} system names','CONSISTENT' if len(nsys)==7 else 'BELOW',''))
NBL.append(mk('NV6','We benchmarked three models in this round: DeepSeek R1, Qwen3-VL 235B, and gpt-oss 120B, in both the server and offline scenarios.','distinct Nebius models and scenarios in the v6.1 file','three models, server and offline',f'{len(mods)} models {mods}; each has Server and Offline: {both}','CONSISTENT' if len(mods)==3 and both else 'BELOW',''))
v36=nb('VR200','deepseek-r1','Server')
NBL.append(mk('NV7','Nebius ran DeepSeek R1 on 36 GPUs across nine nodes on a Nebius system with NVIDIA Vera Rubin NVL72 in the preview category.','Nebius VR200 entry fields','36 GPUs, nine nodes, preview',f'{v36["total_accelerators"]} accelerators, {v36["number_of_nodes"]} nodes, {v36["Availability"]}','CONSISTENT' if (v36['total_accelerators'],v36['number_of_nodes'],v36['Availability'])==(36,9,'preview') else 'BELOW',''))
pg=[(x['Organization'],x['Result']/x['total_accelerators']) for x in vr if x['Scenario']=='Server' and x['Availability']=='preview']
NBL.append(mk('NV8','On that basis, Nebius posted the leading server result at 16,427 tokens/s per GPU','preview DeepSeek R1 Server entries on Vera Rubin, result divided by accelerator count','leading per-GPU Server result, 16,427 tokens/s',', '.join(f'{o} {p:,.0f}' for o,p in sorted(pg,key=lambda t:-t[1])),'CONSISTENT' if max(pg,key=lambda t:t[1])[0]=='Nebius' and round(v36['Result']/36)==16427 else 'BELOW','Nebius is the higher of the two preview entries.'))
r72=nb('(72x GB300','deepseek-r1','Server'); r72o=nb('(72x GB300','deepseek-r1','Offline')
NBL.append(mk('NV9','72 NVIDIA Blackwell Ultra GPUs across 18 nodes served large-scale inference workloads.','Nebius 72 GPU entry fields','72 GPUs, 18 nodes',f'{r72["total_accelerators"]} accelerators, {r72["number_of_nodes"]} nodes','CONSISTENT' if (r72['total_accelerators'],r72['number_of_nodes'])==(72,18) else 'BELOW',''))
NBL.append(mk('NV10','we ranked first in both the server and offline scenarios for DeepSeek R1, at 603,023 and 689,961 tokens/s respectively','Nebius 72 GPU GB300 DeepSeek R1 entries ranked among 72 GPU GB300 entries','first in Server and Offline, 603,023 and 689,961',f'Server {r72["Result"]:,.0f} rank {rank(r72)[0]} of {rank(r72)[1]}, Offline {r72o["Result"]:,.0f} rank {rank(r72o)[0]} of {rank(r72o)[1]}','CONSISTENT' if rank(r72)[0]==1 and rank(r72o)[0]==1 else 'BELOW',''))
g72s,g72o=nb('(72x GB300','gpt-oss-120b','Server'),nb('(72x GB300','gpt-oss-120b','Offline'); g8s,g8o=nb('(8x GB300','gpt-oss-120b','Server'),nb('(8x GB300','gpt-oss-120b','Offline')
NBL.append(mk('NV11','The same full-rack system sustained over 1.1 million tokens/s on gpt-oss 120B in both scenarios','Nebius 72 GPU GB300 gpt-oss 120B entries','over 1.1 million tokens/s in both scenarios',f'Server {g72s["Result"]:,.0f}, Offline {g72o["Result"]:,.0f}','CONSISTENT' if g72s['Result']>1.1e6 and g72o['Result']>1.1e6 else 'BELOW',''))
sx,ox=g72s['Result']/g8s['Result'],g72o['Result']/g8o['Result']
NBL.append(mk('NV12','moving from the eight-GPU GB300 NVL72 configuration to the NVIDIA GB300 NV72 rack, a 9x increase in GPUs, it delivered 8.8x higher server throughput and 9.0x higher offline throughput','Nebius 72 GPU entry over Nebius 8 GPU entry, gpt-oss 120B','9x GPUs, 8.8x Server, 9.0x Offline',f'{72//8}x GPUs, {sx:.2f}x Server ({g72s["Result"]:,.0f} over {g8s["Result"]:,.0f}), {ox:.2f}x Offline ({g72o["Result"]:,.0f} over {g8o["Result"]:,.0f})','CONSISTENT' if round(sx,1)==8.8 and round(ox,1)==9.0 else 'BELOW',''))
g8=sorted({x['Organization'] for x in B if x['Model']=='gpt-oss-120b' and x['Division']=='closed' and x['total_accelerators']==8 and 'GB300' in gi(x['accelerator_model_name'])}); g8a=sorted({x['Organization'] for x in B if x['Division']=='closed' and x['total_accelerators']==8 and 'GB300' in gi(x['accelerator_model_name'])})
NBL.append(mk('NV13','Only two submitters ran that eight-GPU configuration.','closed 8 GPU GB300 entries in the v6.1 file','two submitters',f'gpt-oss 120B: {g8}; any model: {g8a}','CONSISTENT' if len(g8)==2 else 'BELOW','True for gpt-oss 120B. Oracle also has eight-GPU GB300 entries for other models.'))
t8s=max((x for x in grp(g8s)),key=lambda x:x['Result']); t8o=max((x for x in grp(g8o)),key=lambda x:x['Result']); sh=100*(t8s['Result']-g8s['Result'])/t8s['Result']
NBL.append(mk('NV14','Nebius posted the top offline result for gpt-oss 120B and came within 0.2% of the top server result','Nebius 8 GPU GB300 entries against the other 8 GPU GB300 gpt-oss 120B entry','top Offline, within 0.2% of top Server',f'Offline {g8o["Result"]:,.0f} top is {t8o["Organization"]}; Server top {t8s["Organization"]} {t8s["Result"]:,.0f}, Nebius {sh:.2f}% below','CONSISTENT' if t8o['Organization']=='Nebius' and sh<=0.2 else 'BELOW','The post sentence follows the eight-GPU comparison, so the top is read within that group.'))
b2,b3=nb('B200 n1','deepseek-r1','Server'),nb('B300 n1','deepseek-r1','Server'); c2,c3=nb('B200 n1','gpt-oss-120b','Server'),nb('B300 n1','gpt-oss-120b','Server')
NBL.append(mk('NV15','raised server throughput from 55,869 to 63,909 tokens/s on identical eight-GPU configurations','Nebius B200 and B300 DeepSeek R1 Server entries','55,869 to 63,909, eight GPUs',f'{b2["Result"]:,.0f} to {b3["Result"]:,.0f} ({pc(b3["Result"],b2["Result"]):+.1f}%), {b2["total_accelerators"]} and {b3["total_accelerators"]} accelerators','CONSISTENT' if (round(b2['Result']),round(b3['Result']),b2['total_accelerators'],b3['total_accelerators'])==(55869,63909,8,8) else 'BELOW','The entries differ in accelerator model, which is the comparison being made.'))
NBL.append(mk('NV16','from 89,856 to 108,124 tokens/s','Nebius B200 and B300 gpt-oss 120B Server entries','89,856 to 108,124',f'{c2["Result"]:,.0f} to {c3["Result"]:,.0f} ({pc(c3["Result"],c2["Result"]):+.1f}%)','CONSISTENT' if (round(c2['Result']),round(c3['Result']))==(89856,108124) else 'BELOW',''))
rt=[x for x in B if x['Division']=='closed' and x['Model']=='gpt-oss-120b' and x['total_accelerators']==8 and 'RTX' in gi(x['accelerator_model_name'])]; rto=max((x for x in rt if x['Scenario']=='Offline'),key=lambda x:x['Result']); rts=max((x for x in rt if x['Scenario']=='Server'),key=lambda x:x['Result']); nr=nb('RTX PRO 6000','gpt-oss-120b','Server'); sh2=100*(rts['Result']-nr['Result'])/rts['Result']
NBL.append(mk('NV17','That node posted the fastest offline result among all 8x NVIDIA RTX PRO 6000 GPU submissions for gpt-oss 120B and came within 0.3% of the best server result','Nebius RTX PRO 6000 8 GPU entries against all 8 GPU RTX PRO 6000 gpt-oss 120B entries','fastest Offline, within 0.3% of best Server',f'Offline top {rto["Organization"]} {rto["Result"]:,.1f}; Server top {rts["Organization"]} {rts["Result"]:,.1f}, Nebius {sh2:.2f}% below','CONSISTENT' if rto['Organization']=='Nebius' and sh2<=0.3 else 'BELOW',''))
json.dump(dict(source=FILES,sha256=[hashlib.sha256(RAW[f]).hexdigest() for f in FILES],claims=NBL),open('claims_nebius_v61.json','w'),indent=1)
